/* Responsive hardening: keep real customer data readable and inside the viewport. */
html,body{max-width:100%}
.container,.application-content,.portal-panel,.portal-row,.account-command-bar,.account-command-bar>*{min-width:0}
.portal-row strong,.portal-row small,.summary-card strong,.loan-stat-grid strong,.transaction-row,.document-row,.review-item strong,.reference-box strong,.card,.prose,.job{overflow-wrap:anywhere;word-break:normal}

@media(max-width:980px){
  .mobile-panel{overflow-y:auto;overscroll-behavior:contain;padding-bottom:max(24px,env(safe-area-inset-bottom))}
  .mobile-panel a,.mobile-panel .btn{min-height:44px;display:flex;align-items:center}
}

@media(max-width:640px){
  input,select,textarea{font-size:16px}
