  .application-page.smart-application .progress-head strong{font-size:.68rem}
  .application-page.smart-application .step-list li{padding:5px}
  .application-page.smart-application .step-list li strong{display:none}
  .application-page.smart-application .step-list li.active strong{display:block;font-size:.68rem}
  .application-page.smart-application .application-content form{padding:17px 14px 20px;border-radius:16px}
  .application-page.smart-application .form-grid.two{grid-template-columns:1fr 1fr}
  .application-page.smart-application .affordability-summary{grid-template-columns:repeat(2,minmax(0,1fr))!important}
  .application-page.smart-application .form-actions{bottom:6px;margin-left:-4px;margin-right:-4px}
}

@media(max-width:520px){
  .application-page.smart-application .form-grid.two{grid-template-columns:1fr}
  .application-page.smart-application .affordability-summary{grid-template-columns:repeat(2,minmax(0,1fr))!important}
  .smart-identity-summary{align-items:flex-start}
  .smart-identity-summary small{line-height:1.35}
  .application-page.smart-application .form-actions .btn{min-width:0;flex:1}
}

/*
 * KredRun premium theme
 * ------------------------------------------------------------
 * To rebrand the whole app, change the BRAND TOKENS below.
 * Components use semantic variables so pages, forms and portal
 * stay in sync without hunting for colours across many files.
 */

:root {
  /* ========== BRAND TOKENS: edit these first ========== */
  --brand-primary: #0876d8;
  --brand-primary-strong: #0558ad;
  --brand-secondary: #18b5d6;
  --brand-accent: #56c51f;
  --brand-accent-strong: #38a814;
  --brand-ink: #0c2947;
  --brand-navy: #053963;
  --brand-background: #f3f8fc;
  --brand-surface: #ffffff;
  --brand-muted: #668098;
  --brand-line: #d9e6f0;
  --brand-danger: #c6424f;
  --brand-warning: #d8891d;
  --brand-success: #22955f;

  /* RGB helpers for transparent colour use */
  --brand-primary-rgb: 8, 118, 216;
  --brand-accent-rgb: 86, 197, 31;
  --brand-navy-rgb: 5, 57, 99;

  /* ========== SEMANTIC TOKENS ========== */
  --ink: var(--brand-ink);
  --muted: var(--brand-muted);
  --blue: var(--brand-primary);
  --blue-dark: var(--brand-primary-strong);
  --aqua: var(--brand-secondary);
  --navy: var(--brand-navy);
  --cloud: var(--brand-background);
  --line: var(--brand-line);
  --white: var(--brand-surface);
  --success: var(--brand-success);

  --surface: var(--brand-surface);
  --surface-soft: #f7fbfe;
  --surface-tint: #edf6fd;
  --surface-success: #eff9eb;
  --text-on-brand: #ffffff;
  --text-on-dark: #ffffff;
  --hero-muted: #dceeff;

  --gradient-brand: linear-gradient(125deg, var(--brand-primary-strong) 0%, var(--brand-primary) 54%, var(--brand-secondary) 100%);
  --gradient-dark: linear-gradient(145deg, var(--brand-navy) 0%, var(--brand-primary-strong) 100%);
  --gradient-soft: linear-gradient(145deg, #f9fcff 0%, #edf7ff 56%, #f1fbf7 100%);
  --gradient-accent: linear-gradient(135deg, var(--brand-accent) 0%, var(--brand-accent-strong) 100%);

  --shadow-sm: 0 8px 24px rgba(var(--brand-navy-rgb), .07);
  --shadow-md: 0 18px 48px rgba(var(--brand-navy-rgb), .11);
  --shadow-lg: 0 30px 80px rgba(var(--brand-navy-rgb), .17);
  --shadow-accent: 0 14px 30px rgba(var(--brand-accent-rgb), .25);
  --shadow: var(--shadow-md);

  --radius-sm: 12px;
  --radius-md: 18px;
  --radius-lg: 26px;
  --radius-xl: 34px;
  --radius: var(--radius-lg);
}

/* ---------- Global polish ---------- */
body {
  background: var(--surface);
  color: var(--ink);
}

::selection {
  background: rgba(var(--brand-primary-rgb), .16);
  color: var(--ink);
}

.section-soft {
  background:
    radial-gradient(circle at 10% 10%, rgba(var(--brand-primary-rgb), .06), transparent 26%),
    linear-gradient(180deg, var(--surface-soft), var(--brand-background));
}

.card,
.loan-card,
.portal-panel,
.summary-card,
.auth-card,
.progress-card,
.sidebar-help,
.choice-panel,
.received-card,
.contact-card,
.news-card,
.quote {
  transition: transform .22s ease, box-shadow .22s ease, border-color .22s ease;
}

.card:hover,
.news-card:hover {
  transform: translateY(-3px);
  border-color: rgba(var(--brand-primary-rgb), .20);
  box-shadow: var(--shadow-sm);
}

/* ---------- Header / navigation ---------- */
.top-strip {
  background: var(--brand-navy);
  color: #eaf6ff;
  border-bottom: 1px solid rgba(255,255,255,.08);
}

.top-strip .container {
  min-height: 38px;
  font-size: .82rem;
}

.site-header {
  background: rgba(255,255,255,.92);
  border-bottom: 1px solid rgba(var(--brand-primary-rgb), .09);
  box-shadow: 0 8px 28px rgba(var(--brand-navy-rgb), .05);
}

.nav-wrap { min-height: 76px; }

.brand-mark {
  background: var(--gradient-brand);
  border-radius: 14px;
  box-shadow: 0 10px 24px rgba(var(--brand-primary-rgb), .22);
}

.brand span:last-child em { color: var(--brand-accent-strong); }

.nav-link {
  color: #536b80;
  border: 1px solid transparent;
}

.nav-link:hover,
.nav-link.active {
  background: var(--surface-tint);
  color: var(--brand-primary-strong);
  border-color: rgba(var(--brand-primary-rgb), .10);
}

/* ---------- Buttons ---------- */
.btn {
  min-height: 48px;
  padding-inline: 22px;
  border-radius: 14px;
  letter-spacing: -.01em;
}

.btn-primary {
  background: var(--gradient-accent);
  color: var(--text-on-brand);
  border-color: rgba(var(--brand-accent-rgb), .16);
  box-shadow: var(--shadow-accent);
}

.btn-primary:hover {
  background: var(--brand-accent-strong);
  box-shadow: 0 16px 34px rgba(var(--brand-accent-rgb), .30);
}

.btn-outline {
  border-color: var(--brand-line);
  background: rgba(255,255,255,.92);
  color: var(--ink);
}

.btn-outline:hover {
  border-color: rgba(var(--brand-primary-rgb), .34);
  background: var(--surface-tint);
  color: var(--brand-primary-strong);
}

/* ---------- Homepage hero ---------- */
.hero {
  padding: 72px 0 82px;
  color: var(--text-on-brand);
  background:
    radial-gradient(circle at 3% 8%, rgba(255,255,255,.15), transparent 22%),
    radial-gradient(circle at 88% 18%, rgba(255,255,255,.12), transparent 24%),
    var(--gradient-brand);
}

.hero:before {
  content: "";
  position: absolute;
  inset: auto -10% -46% -10%;
  height: 72%;
  border-radius: 50% 50% 0 0 / 22% 22% 0 0;
  background: rgba(255,255,255,.06);
  transform: rotate(-3deg);
}

.hero:after {
  width: 520px;
  height: 520px;
  right: -210px;
  bottom: -260px;
  background: rgba(255,255,255,.07);
}

.hero-grid { gap: 54px; }

.hero .eyebrow {
  color: #cdeaff;
  background: rgba(255,255,255,.10);
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 999px;
  padding: 8px 12px;
  margin-bottom: 18px;
}

.hero .eyebrow:before { display: none; }

.hero-copy .display {
  max-width: 720px;
  text-shadow: 0 6px 26px rgba(var(--brand-navy-rgb), .18);
}

.hero-copy .display span { color: #c9ff80; }
.hero .lead { color: var(--hero-muted); }

.hero-badges { margin-top: 26px; }

.hero .pill {
  color: #f4fbff;
  background: rgba(255,255,255,.10);
  border-color: rgba(255,255,255,.18);
  backdrop-filter: blur(10px);
}

.hero .pill-dot { background: #b9ff78; }

.hero .btn-outline {
  color: #fff;
  background: rgba(255,255,255,.09);
  border-color: rgba(255,255,255,.30);
}

.hero .btn-outline:hover { background: rgba(255,255,255,.16); color: #fff; }

.loan-card {
  color: var(--ink);
  border: 1px solid rgba(255,255,255,.72);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-lg);
  background: rgba(255,255,255,.97);
  backdrop-filter: blur(18px);
}

.loan-card:before {
  height: 5px;
  border-radius: var(--radius-xl) var(--radius-xl) 0 0;
  background: var(--gradient-accent);
}

.loan-card-label { color: var(--brand-primary-strong); }
.loan-amount { color: var(--brand-navy); }

.secure-tag {
  color: #267615;
  background: var(--surface-success);
  border: 1px solid rgba(var(--brand-accent-rgb), .22);
}

input[type=range] { accent-color: var(--brand-accent); }

.loan-summary { gap: 12px; }

.mini-card {
  background: var(--surface-tint);
  border: 1px solid rgba(var(--brand-primary-rgb), .10);
  border-radius: 16px;
}

/* ---------- Trust strip ---------- */
.section-tight {
  padding: 0;
  background: linear-gradient(180deg, var(--surface) 0%, var(--surface-soft) 100%);
}

.section-tight .container { position: relative; z-index: 6; }

.trust-row {
  transform: translateY(-24px);
  grid-template-columns: repeat(4,1fr);
  border: 1px solid rgba(var(--brand-primary-rgb), .10);
  border-radius: 22px;
  box-shadow: var(--shadow-md);
  background: rgba(255,255,255,.97);
}

.trust-item {
  position: relative;
  padding: 22px 20px 22px 54px;
  border-color: var(--brand-line);
}

.trust-item:before {
  content: "✓";
  position: absolute;
  left: 20px;
  top: 24px;
  width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  color: var(--brand-primary);
  background: var(--surface-tint);
  font-size: .75rem;
  font-weight: 900;
}

/* ---------- Rich content cards ---------- */
.cards-3,
.cards-4 { gap: 18px; }

.card {
  border-color: rgba(var(--brand-primary-rgb), .10);
  border-radius: var(--radius-lg);
  box-shadow: 0 8px 26px rgba(var(--brand-navy-rgb), .035);
}

.card-icon {
  background: linear-gradient(145deg, var(--surface-tint), #eaf9f2);
  color: var(--brand-primary);
  border: 1px solid rgba(var(--brand-primary-rgb), .10);
}

.step {
  padding-top: 72px;
  overflow: visible;
}

.step-num {
  width: 46px;
  height: 46px;
  background: var(--gradient-brand);
  box-shadow: 0 9px 20px rgba(var(--brand-primary-rgb), .18);
}

.step:not(:last-child):after {
  top: 23px;
  height: 2px;
  background: linear-gradient(90deg, rgba(var(--brand-primary-rgb),.30), rgba(var(--brand-primary-rgb),.06));
}

.tick {
  width: 28px;
  height: 28px;
  border-radius: 9px;
  background: var(--surface-success);
  color: var(--brand-accent-strong);
  border: 1px solid rgba(var(--brand-accent-rgb), .16);
}

.visual-panel {
  min-height: 460px;
  background:
    radial-gradient(circle at 20% 18%, rgba(255,255,255,.20), transparent 24%),
    var(--gradient-brand);
  border: 1px solid rgba(255,255,255,.18);
  box-shadow: var(--shadow-lg);
}

.phone {
  width: 260px;
  height: 408px;
  background: #0b1725;
  border: 1px solid rgba(255,255,255,.15);
}

.fake-btn { background: var(--gradient-accent); }

.quote {
  background: var(--gradient-soft);
  border-color: rgba(var(--brand-primary-rgb), .12);
  box-shadow: var(--shadow-sm);
}

.faq {
  border-top-color: var(--brand-line);
}

summary:after { color: var(--brand-primary); }

.cta-panel {
  border-radius: var(--radius-xl);
  background:
    radial-gradient(circle at 90% 0, rgba(255,255,255,.16), transparent 25%),
    var(--gradient-brand);
  box-shadow: var(--shadow-lg);
}

/* ---------- Generic internal pages ---------- */
.page-hero {
  background:
    radial-gradient(circle at 90% 8%, rgba(var(--brand-primary-rgb), .08), transparent 26%),
    linear-gradient(180deg, #f7fbff, var(--surface));
  border-bottom-color: rgba(var(--brand-primary-rgb), .10);
}

.breadcrumbs a { color: var(--brand-primary); }

.side-nav {
  padding: 10px;
  border-radius: 18px;
  background: var(--surface-soft);
  border: 1px solid rgba(var(--brand-primary-rgb), .08);
}

.side-nav a.active,
.side-nav a:hover {
  background: var(--surface);
  color: var(--brand-primary-strong);
  box-shadow: var(--shadow-sm);
}

.contact-card,
.rating-score {
  background: var(--gradient-dark);
  box-shadow: var(--shadow-md);
}

.news-art {
  background: linear-gradient(135deg, var(--surface-tint), #edf9f4);
}

.tag {
  background: var(--surface-tint);
  color: var(--brand-primary-strong);
}

/* ---------- Application journey ---------- */
.application-page,
.account-page,
.auth-page {
  background:
    radial-gradient(circle at 95% 6%, rgba(var(--brand-primary-rgb), .05), transparent 25%),
    var(--brand-background);
}

.application-intro {
  background:
    radial-gradient(circle at 90% 20%, rgba(var(--brand-primary-rgb), .07), transparent 28%),
    linear-gradient(180deg, #fbfdff, #f4f9fd);
  border-bottom-color: rgba(var(--brand-primary-rgb), .10);
}

.application-intro h1 { color: var(--brand-navy); }

.application-security {
  border-color: rgba(var(--brand-accent-rgb), .22);
  background: var(--surface-success);
  box-shadow: var(--shadow-sm);
}

.security-icon { background: var(--gradient-accent); }

.progress-card,
.application-content form,
.received-card {
  border-color: rgba(var(--brand-primary-rgb), .10);
  box-shadow: var(--shadow-md);
}

.progress-card { border-radius: 24px; }

.progress-track { background: #e6eef5; }
.progress-track span { background: var(--gradient-brand); }

.step-list li.active {
  background: var(--surface-tint);
  color: var(--brand-navy);
}

.step-list li.active > span {
  background: var(--gradient-brand);
  border-color: transparent;
  box-shadow: 0 7px 18px rgba(var(--brand-primary-rgb), .18);
}

.step-list li.done > span {
  background: var(--surface-success);
  color: var(--brand-accent-strong);
  border-color: rgba(var(--brand-accent-rgb), .22);
}

.sidebar-help {
  background:
    radial-gradient(circle at 100% 0, rgba(255,255,255,.13), transparent 30%),
    var(--gradient-dark);
  border-color: rgba(255,255,255,.08);
  box-shadow: var(--shadow-md);
}

.application-content form {
  border-radius: 30px;
  background: rgba(255,255,255,.98);
}

.step-kicker { color: var(--brand-primary); }

.choice-panel {
  background: var(--gradient-soft);
  border-color: rgba(var(--brand-primary-rgb), .12);
}

.amount-display strong,
.term-header strong { color: var(--brand-primary-strong); }

.field input:not([type=range]):not([type=checkbox]),
.field select,
.field textarea,
.auth-field input,
.auth-field select {
  border-color: var(--brand-line);
  background: #fbfdff;
}

.field input:focus,
.field select:focus,
.field textarea:focus,
.auth-field input:focus,
.auth-field select:focus {
  border-color: var(--brand-primary);
  background: #fff;
  box-shadow: 0 0 0 4px rgba(var(--brand-primary-rgb), .10);
  outline: none;
}

.soft-notice,
.privacy-inline,
.reference-box {
  border-color: rgba(var(--brand-primary-rgb), .14);
  background: var(--surface-tint);
}

.upload-card {
  background: #fbfdff;
  border-color: #b9cfe0;
}

.upload-card:hover {
  border-color: var(--brand-primary);
  background: var(--surface-tint);
}

.upload-icon,
.privacy-inline > span {
  background: var(--surface-tint);
  color: var(--brand-primary);
}

.review-section,
.consent-box {
  border-color: rgba(var(--brand-primary-rgb), .10);
}

.review-section-head,
.consent-box {
  background: var(--surface-soft);
}

.received-icon {
  background: var(--surface-success);
  color: var(--brand-accent-strong);
}

/* ---------- Authentication ---------- */
.auth-copy h1 { color: var(--brand-navy); }

.auth-point span {
  background: var(--surface-tint);
  color: var(--brand-primary);
}

.auth-card {
  border-color: rgba(var(--brand-primary-rgb), .10);
  border-radius: 28px;
  box-shadow: var(--shadow-md);
}

.auth-tabs {
  background: var(--brand-background);
  border: 1px solid rgba(var(--brand-primary-rgb), .08);
}

.auth-tabs button.active {
  color: var(--brand-primary-strong);
  box-shadow: var(--shadow-sm);
}

.auth-link,
.auth-note a { color: var(--brand-primary); }

/* ---------- Customer portal ---------- */
.account-shell { padding-top: 54px; }

.portal-head {
  padding: 28px 30px;
  align-items: center;
  border-radius: 28px;
  color: #fff;
  background:
    radial-gradient(circle at 85% 10%, rgba(255,255,255,.14), transparent 26%),
    var(--gradient-brand);
  box-shadow: var(--shadow-lg);
}

.portal-head .eyebrow,
.portal-head p { color: #dceeff; }

.portal-head .eyebrow:before { background: #dceeff; }
.portal-head h1 { color: #fff; }

.portal-head .btn-outline {
  background: rgba(255,255,255,.10);
  border-color: rgba(255,255,255,.30);
  color: #fff;
}

.portal-tabs {
  margin: 22px 0 26px;
  padding: 6px;
  border-radius: 18px;
  background: rgba(255,255,255,.78);
  border: 1px solid rgba(var(--brand-primary-rgb), .08);
  box-shadow: var(--shadow-sm);
}

.portal-tabs button {
  border: 0;
  background: transparent;
  border-radius: 13px;
  color: var(--brand-muted);
  font-weight: 750;
}

.portal-tabs button.active {
  background: var(--surface);
  color: var(--brand-primary-strong);
  box-shadow: var(--shadow-sm);
}

.portal-panel {
  border-color: rgba(var(--brand-primary-rgb), .10);
  border-radius: 26px;
  box-shadow: var(--shadow-sm);
}

.summary-card {
  position: relative;
  overflow: hidden;
  border-color: rgba(var(--brand-primary-rgb), .10);
  border-radius: 20px;
  background: linear-gradient(180deg, #fff, #f8fbfe);
  box-shadow: var(--shadow-sm);
}

.summary-card:after {
  content: "";
  position: absolute;
  width: 74px;
  height: 74px;
  border-radius: 50%;
  right: -24px;
  top: -28px;
  background: rgba(var(--brand-primary-rgb), .07);
}

.summary-card strong { color: var(--brand-primary-strong); }

.portal-row {
  border-color: rgba(var(--brand-primary-rgb), .10);
  background: #fbfdff;
}

.portal-row:hover {
  background: var(--surface-tint);
  border-color: rgba(var(--brand-primary-rgb), .18);
}

.portal-kicker,
.text-button,
.document-row b { color: var(--brand-primary); }

.status-approved,
.status-active,
.status-paid {
  background: var(--surface-success);
  color: #28763e;
}

.loan-detail-head h2 { color: var(--brand-primary-strong); }

/* ---------- Footer ---------- */
.site-footer {
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(circle at 86% -30%, rgba(255,255,255,.10), transparent 30%),
    linear-gradient(135deg, var(--brand-navy), var(--brand-primary-strong));
}

.site-footer:before {
  content: "";
  position: absolute;
  width: 520px;
  height: 260px;
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 50%;
  right: -140px;
  bottom: -170px;
  transform: rotate(-8deg);
}

.site-footer .brand span:last-child em { color: #9fe35d; }

/* ---------- Mobile ---------- */
@media (max-width: 980px) {
  .hero { padding-top: 56px; }
  .hero-grid { gap: 34px; }
  .trust-row { grid-template-columns: repeat(2,1fr); }
  .trust-item:nth-child(2) { border-right: 0; }
  .trust-item:nth-child(-n+2) { border-bottom: 1px solid var(--brand-line); }
  .portal-head { align-items: flex-start; }
}

@media (max-width: 720px) {
  .top-strip .container span { display: none; }
  .hero { padding: 44px 0 58px; }
  .hero-copy .display { font-size: clamp(2.35rem, 12vw, 3.65rem); }
  .loan-card { padding: 22px 18px; border-radius: 24px; }
  .loan-card:before { border-radius: 24px 24px 0 0; }
  .trust-row { transform: translateY(-14px); grid-template-columns: 1fr; }
  .trust-item { border-right: 0; border-bottom: 1px solid var(--brand-line); }
  .trust-item:last-child { border-bottom: 0; }
  .portal-head { padding: 24px 20px; border-radius: 22px; }
  .portal-head .account-action-row { width: 100%; }
  .portal-head .account-action-row .btn { flex: 1; }
  .portal-tabs { border-radius: 15px; }
  .application-content form { box-shadow: var(--shadow-sm); }
}

@media (prefers-reduced-motion: reduce) {
  *, *:before, *:after {
    scroll-behavior: auto !important;
    transition-duration: .01ms !important;
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
  }
}
